-- 23763
SELECT MAX(Y.CONSUMPTION / 12) AS BIGGESTMONTHLYCONSUMPTION FROM CUSTOMERS C JOIN YEARMONTH Y ON C.CUSTOMERID = Y.CUSTOMERID WHERE C.CURRENCY = 'EUR';
