-- -32212, 2147483648, 2147483648
SELECT SUM(CST.POINTS) AS TOTAL_POINTS, C.NAME AS CONSTRUCTOR_NAME, C.NATIONALITY AS CONSTRUCTOR_NATIONALITY FROM RACES R JOIN CONSTRUCTORSTANDINGS CST ON R.RACEID = CST.RACEID JOIN CONSTRUCTORS C ON CST.CONSTRUCTORID = C.CONSTRUCTORID WHERE R.NAME = 'MONACO GRAND PRIX' AND R.YEAR BETWEEN 1980 AND 2010 GROUP BY C.CONSTRUCTORID ORDER BY TOTAL_POINTS DESC LIMIT 1;
-- ----------sql2------------
-- 5825, 2147483648, 2147483648
SELECT SUM(T1.POINTS), T2.NAME, T2.NATIONALITY FROM CONSTRUCTORRESULTS AS T1 INNER JOIN CONSTRUCTORS AS T2 ON T1.CONSTRUCTORID = T2.CONSTRUCTORID INNER JOIN RACES AS T3 ON T3.RACEID = T1.RACEID WHERE T3.NAME = 'MONACO GRAND PRIX' AND T3.YEAR BETWEEN 1980 AND 2010 GROUP BY T2.NAME ORDER BY SUM(T1.POINTS) DESC LIMIT 1;

